def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find maximal diagonal runs of a non-background color. Extend only
    # interior runs, stopping at any other non-background cell or the edge.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue

                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc

                if len(run) < 2:
                    continue
                if any(x in (0, h - 1) or y in (0, w - 1) for x, y in run):
                    continue

                for rr, cc, sr, sc in (
                    (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                    (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
